insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_111_v1'
from (values
('127.811.d.1.A',3,'A new machinist must explain a delay to a shift supervisor in person and then document it for the purchasing office and a supplier in another country. She is demonstrating effective oral and written communication with:','["individuals from varied backgrounds and roles", "only people who agree", "only close friends", "only family members"]'::jsonb,0,'Different audiences need clear communication.','original'),
('127.811.d.1.A',4,'When writing to a supplier in another country, the clearest approach is to:','["use only abbreviations", "use plain, precise language and include measurements with units", "leave out dimensions", "use slang and jokes"]'::jsonb,1,'Plain precise language travels well.','original'),
('127.811.d.1.B',3,'A fabricator reads a print that shows a fillet weld symbol, a dimension callout and a section view before cutting any metal. He is interpreting:','["a seating chart", "a weather map", "engineering drawings, charts, diagrams and welding symbols", "a recipe card"]'::jsonb,2,'Prints tell how a part is built.','original'),
('127.811.d.1.B',4,'On an engineering drawing, a dimension callout tells the worker:','["the color of the paint", "the weight of the shipping box", "the name of the buyer", "the size the feature must be made"]'::jsonb,3,'Dimensions control size.','original'),
('127.811.d.1.C',3,'To drill a bolt circle of six equally spaced holes, a student uses geometry to find the angle between holes and algebra to find hole coordinates. She is selecting:','["algebraic and geometric principles for precision measurement and calculation", "a music scale", "a poem structure", "a paint color"]'::jsonb,0,'Math supports precision layout.','original'),
('127.811.d.1.C',4,'The angle between six equally spaced holes on a circle is:','["45 degrees", "60 degrees", "30 degrees", "90 degrees"]'::jsonb,1,'360 ÷ 6 = 60.','original'),
('127.811.d.2.A',3,'Before running a drill press, a student clamps the workpiece, ties back long hair and puts on safety glasses. He is using shop equipment:','["in a hurry", "without guards", "in a safe manner", "without preparation"]'::jsonb,2,'Safe setup prevents injuries.','original'),
('127.811.d.2.A',4,'The main reason to clamp a part before drilling is to:','["speed the drill", "make the hole bigger", "make it heavier", "keep it from spinning or lifting out of the vise"]'::jsonb,3,'Clamping prevents accidents.','original'),
('127.811.d.2.B',3,'A lathe has a chuck guard and a posted rule against wearing loose sleeves, while a grinder has a tool rest and a spark guard. Students are learning:','["safety regulations for different types of manufacturing equipment", "office etiquette", "menu design", "music theory"]'::jsonb,0,'Each machine has its own rules.','original'),
('127.811.d.2.B',4,'A rule that applies when working near rotating machinery is to avoid:','["safety glasses", "loose clothing, jewelry and dangling items", "a tied-back hairstyle", "a clear work area"]'::jsonb,1,'Loose items can catch.','original'),
('127.811.d.2.C',3,'A class turns a brass pin on a lathe, mills a flat on a block and welds two bars together following written procedures. They are executing procedures with:','["kitchen appliances", "office software", "different types of manufacturing equipment", "garden tools"]'::jsonb,2,'Procedures guide equipment use.','original'),
('127.811.d.2.C',4,'A machine that removes material by spinning a workpiece against a cutting tool is a:','["printer", "loom", "kiln", "lathe"]'::jsonb,3,'Lathes turn workpieces.','original'),
('127.811.d.2.D',3,'A class compares aluminum, stainless steel, carbon fiber and engineered plastics for strength, weight and cost before choosing a bracket material. They are researching:','["modern materials used in manufacturing", "old recipes", "folk songs", "farm crops"]'::jsonb,0,'Material choice drives design.','original'),
('127.811.d.2.D',4,'A reason engineers choose carbon fiber composites for some parts is:','["heavy mass", "a high strength-to-weight ratio", "very low cost", "easy to melt"]'::jsonb,1,'Strong yet light.','original'),
('127.811.d.2.E',3,'A technician measures a shaft with a micrometer to the nearest thousandth of an inch and records the reading. She is performing:','["tasting tests", "visual estimates only", "varied measurements, including precision measurements", "rough guesses"]'::jsonb,2,'Precision tools give accuracy.','original'),
('127.811.d.2.E',4,'A caliper is commonly used in a shop to measure:','["temperature", "sound level", "humidity", "outside and inside dimensions and depths"]'::jsonb,3,'Calipers measure lengths and depths.','original'),
('127.811.d.3.A',3,'A student presents a report on how additive manufacturing is used to print lightweight aircraft brackets. She is reporting on:','["innovative applications of technology in engineering", "a family recipe", "old fashions", "last year''s sports scores"]'::jsonb,0,'Cutting-edge tech examples.','original'),
('127.811.d.3.A',4,'Another name for 3D printing in industry is:','["casting only", "additive manufacturing", "subtractive carving only", "stamping only"]'::jsonb,1,'Additive builds layer by layer.','original'),
('127.811.d.3.B',3,'A team tries a laser cutter on acrylic for the first time and compares the results with a handsaw to see how the new tool changes accuracy. They are:','["copying old methods", "avoiding new tools", "experimenting with new technologies", "skipping tests"]'::jsonb,2,'Experiments reveal what works.','original'),
('127.811.d.3.B',4,'When experimenting with a new tool, students should first:','["ignore instructions", "use it on the final part", "skip training", "read the safety information and test on scrap"]'::jsonb,3,'Test on scrap first.','original'),
('127.811.d.3.C',3,'A class forms identical coupons from plastic, fiberglass composite and wood, then tests how much load each can hold. They are experimenting with:','["different manufacturing materials", "different shoe styles", "different team colors", "different pizza toppings"]'::jsonb,0,'Compare materials by testing.','original'),
('127.811.d.3.C',4,'A composite material is made by:','["drying clay only", "combining two or more materials to gain properties neither has alone", "cutting wood only", "melting one metal"]'::jsonb,1,'Composites combine materials.','original'),
('127.811.d.4.A',3,'A team lists tasks, assigns people, sets milestones and checks results against the plan as they build a part. They are analyzing the processes of a project such as:','["buying, selling and trading", "sleeping, eating and playing", "initiating, planning, executing, monitoring and closing", "starting, stopping and waiting"]'::jsonb,2,'Project phases organize work.','original'),
('127.811.d.4.A',4,'The final phase of a project, in which the results are reviewed and lessons are recorded, is:','["executing", "initiating", "planning", "closing"]'::jsonb,3,'Closure wraps up.','original'),
('127.811.d.4.B',3,'A class sets up a drill press, a band saw and a sander to produce a bracket that meets the drawing''s tolerance. They are using:','["a variety of equipment and machines to produce an item to specification", "only hand tools", "no tools", "one tool only"]'::jsonb,0,'Several machines meet specs.','original'),
('127.811.d.4.B',4,'A tolerance on a drawing tells the machinist:','["what color to paint", "how much a dimension is allowed to vary", "how fast to cut", "who ordered the part"]'::jsonb,1,'Tolerance = allowed variation.','original'),
('127.811.d.5.A',3,'A student earns a shop-safety certificate by passing a test based on federal workplace safety rules covering machine guards, protective gear and emergency procedures. She is mastering:','["a geography quiz", "a typing test", "safety tests developed from OSHA guidelines and regulations", "a driving test"]'::jsonb,2,'OSHA-based testing.','original'),
('127.811.d.5.A',4,'Protective gear such as safety glasses and hearing protection is called:','["optional extras", "decoration", "toys", "personal protective equipment (PPE)"]'::jsonb,3,'PPE protects workers.','original'),
('127.811.d.5.B',3,'A technician reads the label and safety data sheet on a cutting fluid and notes it is a skin irritant and must not be mixed with certain solvents. He is analyzing:','["hazardous materials", "art supplies only", "lunch items", "office supplies"]'::jsonb,0,'Read labels and sheets.','original'),
('127.811.d.5.B',4,'A safety data sheet is best used to find:','["the store location", "a chemical''s hazards and safe handling", "the product price", "the logo design"]'::jsonb,1,'SDS explains hazards.','original'),
('127.811.d.5.C',3,'Used solvent rags are placed in a labeled, approved metal container rather than the regular trash. This shows how to:','["hide waste", "burn waste", "dispose of hazardous materials safely", "pour waste outside"]'::jsonb,2,'Proper disposal prevents fires.','original'),
('127.811.d.5.C',4,'Used oily rags are typically stored in:','["a plastic bag in the sun", "the regular trash", "an open cardboard box", "an approved closed metal container"]'::jsonb,3,'Prevents spontaneous combustion.','original'),
('127.811.d.5.D',3,'A shop stores flammable liquids in a labeled flammables cabinet away from welding sparks and keeps different chemicals separated. This is how to:','["store all materials correctly", "store anywhere", "store everything together", "store in the open"]'::jsonb,0,'Correct storage prevents accidents.','original'),
('127.811.d.5.D',4,'Flammable liquids should be stored:','["next to a heater", "in an approved flammables cabinet", "in open buckets", "on the floor by the door"]'::jsonb,1,'Use an approved cabinet.','original'),
('127.811.d.6.A',3,'A class forms a production line to make fifty identical key chains, with each student doing one step. They are participating in the manufacturing of:','["a single prototype", "a family photo", "a mass-produced project", "a one-off sculpture"]'::jsonb,2,'Mass production divides work.','original'),
('127.811.d.6.A',4,'A key advantage of dividing a task among a production line is:','["lower quality", "random results", "slower output", "consistent work done faster"]'::jsonb,3,'Specialization speeds work.','original'),
('127.811.d.6.B',3,'A student measures every tenth key chain with a gauge and records the results on a chart to catch any drift from the target size. She is developing a method to:','["check and maintain quality control throughout manufacturing", "skip inspection", "hide errors", "decorate parts"]'::jsonb,0,'Sampling checks quality.','original'),
('127.811.d.6.B',4,'Inspecting a sample of parts from a production run is a way to:','["avoid testing", "catch problems before many bad parts are made", "make parts heavier", "increase defects"]'::jsonb,1,'Sampling prevents waste.','original'),
('127.811.d.7.A',3,'A team totals the cost of material, labor and tool wear for a batch of brackets and compares it with the selling price. They are developing a:','["travel brochure", "party invitation", "budget for a project", "playlist"]'::jsonb,2,'Budgets plan costs.','original'),
('127.811.d.7.A',4,'Before starting a class manufacturing run, a team compares what the materials and labor will cost against the funds the program has. This comparison is the core of a:','["shipping label", "parts diagram", "safety poster", "project budget"]'::jsonb,3,'A budget matches expected costs to available funds.','original'),
('127.811.d.7.B',3,'A class finds that nesting parts on one sheet of steel wastes less material than cutting from many sheets. They are determining:','["the most effective strategies to minimize costs", "a way to raise prices only", "a way to waste more", "a way to avoid planning"]'::jsonb,0,'Reduce waste to cut costs.','original'),
('127.811.d.7.B',4,'One way a plant lowers cost per part is by:','["using more material", "reducing scrap and rework", "adding defects", "slowing the line"]'::jsonb,1,'Less waste, lower cost.','original'),
('127.811.d.8.A',3,'A student team writes a plan for selling their key chains that names the buyer, the price, where to advertise and a launch date. They are preparing:','["a seating chart", "a lunch menu", "a marketing plan for a product", "a game roster"]'::jsonb,2,'Marketing plans promote products.','original'),
('127.811.d.8.A',4,'A marketing plan should identify:','["only the product color", "only the cost of paint", "only the factory name", "the target customers and how to reach them"]'::jsonb,3,'Know your audience.','original'),
('127.811.d.8.B',3,'After several customers return a product because it breaks easily, sales drop and online reviews turn negative. Students are analyzing the effect of:','["customer satisfaction on the image of a product", "sports on health", "music on homework", "weather on traffic"]'::jsonb,0,'Satisfaction shapes reputation.','original'),
('127.811.d.8.B',4,'Happy customers are most likely to:','["return everything", "recommend the product and buy again", "post complaints", "avoid the brand"]'::jsonb,1,'Loyalty follows satisfaction.','original'),
('127.811.d.8.C',3,'Survey results show buyers want a lighter, rechargeable flashlight, so the design team changes the housing and battery. They are analyzing how:','["fog affects visibility", "sunlight affects sleep", "customer demands influence the design of an object", "price tags affect color"]'::jsonb,2,'Design follows demand.','original'),
('127.811.d.8.C',4,'When customers repeatedly ask for a feature, a company often:','["ignores the request", "raises price only", "stops selling", "redesigns the product to include it"]'::jsonb,3,'Demand drives design.','original'),
('127.811.d.9.A',3,'During a team meeting, a lead tells the crew the order of operations, the tolerances and the inspection points in plain terms and asks each member to repeat it back. She is demonstrating:','["communication techniques consistent with industry standards", "silence", "guesswork", "rumor-passing"]'::jsonb,0,'Standard communication prevents mistakes.','original'),
('127.811.d.9.A',4,'A shift handoff note on a machine should include:','["unrelated stories", "the job status, problems and next steps", "jokes", "opinions about coworkers"]'::jsonb,1,'Handoffs pass key info.','original'),
('127.811.d.9.B',3,'A machinist cannot remember the correct feed rate for stainless steel, so she checks a machinist''s handbook and the tool maker''s catalog. She is:','["skipping the job", "guessing", "locating relevant information needed to solve problems", "asking a stranger"]'::jsonb,2,'Reference materials give data.','original'),
('127.811.d.9.B',4,'A machinist''s handbook is a reliable source for:','["celebrity news", "menus", "sports scores", "speeds, feeds and standard dimensions"]'::jsonb,3,'Handbooks give shop data.','original'),
('127.811.d.9.C',3,'To cut a 3.5-meter pipe into four equal sections, a worker divides the length and marks each cut. He is applying:','["mathematics concepts to solve manufacturing problems", "music theory", "dance steps", "cooking skills"]'::jsonb,0,'Division finds equal lengths.','original'),
('127.811.d.9.C',4,'Each of four equal sections cut from a 3.5-meter pipe is:','["1.0 meters", "0.875 meters", "0.75 meters", "1.25 meters"]'::jsonb,1,'3.5 ÷ 4 = 0.875.','original'),
('127.811.d.9.D',3,'A technician explains that a heated steel rod grows slightly longer because its particles move farther apart, so the shop leaves expansion gaps in long rails. She is analyzing:','["travel plans", "sports history", "science principles used to solve problems", "fashion trends"]'::jsonb,2,'Thermal expansion matters.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_111_v1'
from (values
('127.811.d.9.D',4,'Most metals, when heated, will:','["disappear", "shrink", "turn to powder", "expand"]'::jsonb,3,'Thermal expansion.','original'),
('127.811.d.9.E',3,'A purchasing clerk checks that the order lists the pipe length in meters and the diameter in millimeters to match the shop''s drawings. She is using:','["appropriate units of measure", "no units", "mixed units", "random units"]'::jsonb,0,'Consistent units prevent errors.','original'),
('127.811.d.9.E',4,'The SI base unit of length is the:','["foot", "meter", "mile", "yard"]'::jsonb,1,'Meter is the SI unit of length.','original'),
('127.812.d.1.A',3,'A second-year technician leads a briefing for a crew, then emails a written work order to the client''s engineer and a vendor overseas. She is demonstrating effective oral and written communication with:','["only classmates", "only the crew", "individuals from varied roles and backgrounds", "only her friends"]'::jsonb,2,'Audiences differ; messages must fit.','original'),
('127.812.d.1.A',4,'A written work order sent to an outside vendor should be:','["vague and brief", "written without dates", "full of slang", "clear, complete and specific about requirements"]'::jsonb,3,'Clarity prevents errors.','original'),
('127.812.d.1.B',3,'A welder checks the arrow side of a weld symbol, the weld size and the field-weld flag on a drawing before striking an arc. She is interpreting:','["engineering drawings, charts, diagrams and welding symbols", "a movie script", "a seating map", "a grocery receipt"]'::jsonb,0,'Symbols specify the weld.','original'),
('127.812.d.1.B',4,'On a welding symbol, the reference line, the arrow and the tail together tell the welder:','["which break room to use", "what weld to make, where and how", "who the customer is", "when lunch starts"]'::jsonb,1,'Symbol anatomy gives instructions.','original'),
('127.812.d.1.C',3,'A machinist calculates the diagonal of a rectangular plate with the Pythagorean theorem to check that a part will fit a fixture. He is selecting:','["a recipe ratio", "a music chord", "algebraic and geometric principles required for precision measurement and calculation", "a poem form"]'::jsonb,2,'Geometry supports fit-checks.','original'),
('127.812.d.1.C',4,'A rectangular plate is 3 inches by 4 inches. Its diagonal is:','["12 inches", "6 inches", "7 inches", "5 inches"]'::jsonb,3,'3-4-5 right triangle.','original'),
('127.812.d.1.D',3,'Before ordering 500 identical brackets, a team draws a flow chart of each operation, lists the materials and times each step. They are developing the information needed to:','["mass produce a simple project", "bake cookies", "plan a trip", "write a song"]'::jsonb,0,'Process planning supports mass production.','original'),
('127.812.d.1.D',4,'A flow process chart is useful in mass production because it:','["shows the weather", "shows the sequence of steps and where delays occur", "lists the team''s hobbies", "hides the process"]'::jsonb,1,'Charts reveal the sequence.','original'),
('127.812.d.1.E',3,'A shop builds a block with locating pins so each bracket can be clamped in exactly the same place for drilling every time. The class is exploring the use of:','["paint cans", "ladders", "jigs and fixtures in mass production", "extension cords"]'::jsonb,2,'Jigs and fixtures hold and guide work.','original'),
('127.812.d.1.E',4,'A jig differs from a fixture because it:','["has no purpose", "cannot hold parts", "is only decoration", "guides the cutting tool as well as holding the part"]'::jsonb,3,'Jigs guide tools.','original'),
('127.812.d.2.A',3,'A student sets the guard, secures the workpiece and checks that the sander''s emergency stop works before turning it on. She is using shop tools and equipment:','["in a safe manner", "carelessly", "without checks", "in a hurry"]'::jsonb,0,'Safe use starts with checks.','original'),
('127.812.d.2.A',4,'Before starting any machine, a student should confirm:','["the clock is right", "the guards are in place and the emergency stop works", "the room is warm", "the music is on"]'::jsonb,1,'Pre-use checks.','original'),
('127.812.d.2.B',3,'A grinder operator always keeps the tool rest within an eighth inch of the wheel and never removes the wheel guard. She is adhering to:','["cafeteria rules", "playground rules", "safety regulations for different types of manufacturing equipment", "classroom decor rules"]'::jsonb,2,'Equipment rules prevent injuries.','original'),
('127.812.d.2.B',4,'If a safety guard on a machine is missing, the correct action is to:','["remove other guards", "ignore it", "use the machine carefully", "stop and report it before using the machine"]'::jsonb,3,'Report missing guards.','original'),
('127.812.d.2.C',3,'A team follows the written setup sheet to run a CNC lathe, mill a keyway on a milling machine and weld a frame. They are executing procedures with:','["different types of manufacturing equipment", "different vehicles", "different musical instruments", "different sports gear"]'::jsonb,0,'Procedures guide each machine.','original'),
('127.812.d.2.C',4,'A setup sheet for a machine typically lists:','["party plans", "tools, speeds, feeds and the order of operations", "jokes", "lunch orders"]'::jsonb,1,'Setup sheets guide operations.','original'),
('127.812.d.2.D',3,'A quality inspector checks a hole''s diameter with a bore gauge and a flatness with a dial indicator. She is performing:','["visual guesses", "rough estimates", "varied measurements, including precision measurements", "taste checks"]'::jsonb,2,'Different gauges for different features.','original'),
('127.812.d.2.D',4,'A dial indicator is mostly used to measure:','["weight", "volume of liquids", "room temperature", "small variations such as runout and flatness"]'::jsonb,3,'Indicators detect tiny variation.','original'),
('127.812.d.2.E',3,'A student designs a drilling jig with two bushings and a clamp plate for a bracket with three holes and a flat base. She is designing and developing:','["jigs and fixtures for a simple product of four or fewer parts", "a lunch plan", "a toy only", "a poster"]'::jsonb,0,'Design jigs for the product.','original'),
('127.812.d.2.E',4,'A drill bushing in a jig helps to:','["heat the part", "guide the drill so holes land in the right place", "paint the part", "sort the parts"]'::jsonb,1,'Bushings guide drills.','original'),
('127.812.d.2.F',3,'On run-off day, the class sets up stations, divides the steps and builds one hundred brackets using the jigs. They are participating in:','["a quiz", "a field trip", "the production run of the product", "a lecture"]'::jsonb,2,'Run-off puts the plan into action.','original'),
('127.812.d.2.F',4,'During a production run, the main benefit of jigs and fixtures is:','["more variation", "slower work", "more scrap", "consistent parts from one piece to the next"]'::jsonb,3,'Repeatability.','original'),
('127.812.d.3.A',3,'A student draws a part in software, then uses a program to generate tool paths and code for a mill. She is developing:','["a CNC program using a computer-aided manufacturing (CAM) program", "a song", "a hand drawing", "a quilt pattern"]'::jsonb,0,'CAM creates tool paths.','original'),
('127.812.d.3.A',4,'CAM software is used to:','["edit photos", "create tool paths and machine instructions from a design", "compose music", "write novels"]'::jsonb,1,'CAM = computer-aided manufacturing.','original'),
('127.812.d.3.B',3,'Before cutting aluminum, a student runs the CNC program in simulation mode to see whether the tool crashes into the clamps. She is:','["skipping verification", "deleting the file", "executing the CNC program to machine a product or run a simulation", "guessing"]'::jsonb,2,'Simulations catch errors.','original'),
('127.812.d.3.B',4,'A major reason to simulate a CNC program before cutting is to:','["avoid learning", "make it louder", "slow production", "catch collisions and errors without damaging parts"]'::jsonb,3,'Simulation saves parts and tools.','original'),
('127.812.d.4.A',3,'A student investigates how robotic welding cells and additive manufacturing are changing factories and writes a summary. She is researching:','["innovative technologies in manufacturing", "last year''s fashion", "pop songs", "local weather"]'::jsonb,0,'Explore current innovation.','original'),
('127.812.d.4.A',4,'Collaborative robots, or cobots, are designed to:','["work only in the dark", "work safely alongside humans in a shared space", "replace all factories", "operate without any controls"]'::jsonb,1,'Cobots share workspaces.','original'),
('127.812.d.4.B',3,'A class tests how nylon, aluminum and a glass-filled composite hold up after repeated bending to choose the best clip material. They are experimenting with:','["different hats", "different games", "different manufacturing materials", "different snacks"]'::jsonb,2,'Experiments guide material selection.','original'),
('127.812.d.4.B',4,'When comparing materials for a part, an engineer first considers:','["the day of the week", "the color of the package", "the brand''s logo", "the properties the part needs, such as strength and weight"]'::jsonb,3,'Match properties to needs.','original'),
('127.812.d.5.A',3,'A team studies how stress, strength and stiffness of a beam depend on the material and its shape before choosing a design. They are analyzing:','["engineering properties of materials and designs", "weather forecasts", "cooking times", "playground games"]'::jsonb,0,'Properties guide design.','original'),
('127.812.d.5.A',4,'A material that returns to its original shape after a load is removed is said to be:','["brittle only", "elastic", "gaseous", "liquid"]'::jsonb,1,'Elastic recovers shape.','original'),
('127.812.d.5.B',3,'A class writes a project plan with a charter, schedule, tasks, checkpoints and a final review for their production run. They are analyzing the processes of a project such as:','["starting, drifting and quitting", "buying, saving and spending", "initiating, planning, executing, monitoring and closing", "eating, resting and sleeping"]'::jsonb,2,'Project phases.','original'),
('127.812.d.5.B',4,'In the monitoring phase of a project, the team:','["finishes the plan", "never reviews work", "ignores problems", "checks progress against the plan and adjusts"]'::jsonb,3,'Monitor and control.','original'),
('127.812.d.5.C',3,'A team selects from calipers, a mill, a drill press and a deburring tool to produce a part to the print''s tolerance. They are using:','["a variety of tools and equipment to produce a product to specification", "a single guess", "only one tool", "no tools"]'::jsonb,0,'Right tools meet specs.','original'),
('127.812.d.5.C',4,'A part is made ''to specification'' when it:','["is colorful", "meets all the dimensions and tolerances on the print", "is heavy", "looks good"]'::jsonb,1,'Specs define acceptance.','original'),
('127.812.d.6.A',3,'To work in the shop, a student must pass an exam on machine guarding, lockout/tagout, PPE and hazard communication rooted in federal workplace rules. She is mastering:','["a typing test", "a spelling quiz", "safety tests based on OSHA regulations", "a trivia game"]'::jsonb,2,'OSHA-based training.','original'),
('127.812.d.6.A',4,'Lockout/tagout procedures are used to:','["speed production", "paint the floor", "decorate a shop", "keep a machine from starting during maintenance"]'::jsonb,3,'LOTO protects workers.','original'),
('127.812.d.6.B',3,'A technician reads the safety data sheet on a degreaser to learn its flash point, required gloves and first-aid steps. She is analyzing:','["hazardous materials", "pizza toppings", "school posters", "playground gear"]'::jsonb,0,'SDS details hazards.','original'),
('127.812.d.6.B',4,'A flash point tells a worker:','["the pour speed", "the lowest temperature at which a liquid gives off ignitable vapors", "the color intensity", "the boiling price"]'::jsonb,1,'Flash point = ignition risk.','original'),
('127.812.d.6.C',3,'Waste coolant is collected in a labeled drum and picked up by an authorized hauler instead of being poured down a drain. This demonstrates how to:','["burn it", "dump in a ditch", "dispose of hazardous materials properly", "hide waste"]'::jsonb,2,'Proper disposal protects the environment.','original'),
('127.812.d.6.C',4,'Used coolant and oils should be:','["poured outside", "buried in the yard", "burned in a barrel", "collected and disposed of through an approved process"]'::jsonb,3,'Approved disposal only.','original'),
('127.812.d.6.D',3,'Compressed gas cylinders are chained upright, capped when not in use and stored away from flammables. This shows how to:','["store all materials safely", "store them loosely", "store them near heat", "store them in a pile"]'::jsonb,0,'Proper storage prevents accidents.','original'),
('127.812.d.6.D',4,'A welding shop keeps two full oxygen tanks near its torch cart. Which storage practice is correct?','["lay them flat on the floor", "chain them upright and keep the valve caps on", "lean them against a wall unsecured", "remove the caps for quick access"]'::jsonb,1,'Secured upright cylinders with caps are safest.','original'),
('127.812.d.7.A',3,'Following the process chart, students operate each station to make a batch of identical parts to the plan. They are participating in:','["a spelling bee", "a rehearsal for a play", "the manufacturing of products", "a bake sale"]'::jsonb,2,'Production applies the plan.','original'),
('127.812.d.7.A',4,'In a production setting, each worker at a station is responsible for:','["changing tolerances", "inventing a new step", "skipping steps", "completing a specific step to the standard"]'::jsonb,3,'Stations have defined duties.','original'),
('127.812.d.7.B',3,'A team uses a control chart to plot the diameter of a sample of parts every fifteen minutes and flags any drift outside the limits. They are developing:','["a method to check and maintain quality control", "a seating plan", "a pricing plan", "a decorating plan"]'::jsonb,0,'Control charts track quality.','original'),
('127.812.d.7.B',4,'A control limit on a quality chart shows:','["the best price", "the range within which the process is considered stable", "the customer count", "the shop temperature"]'::jsonb,1,'Limits flag instability.','original'),
('127.812.d.8.A',3,'A student totals the cost of raw stock, machine time, labor and tooling and divides by the number of parts to find the cost per part. She is calculating:','["a grade average", "a travel distance", "costs associated with production of a mass-produced product", "a sports score"]'::jsonb,2,'Cost per part.','original'),
('127.812.d.8.A',4,'If a batch of 200 parts costs $1,000 to produce, the cost per part is:','["$20", "$2", "$10", "$5"]'::jsonb,3,'1000 ÷ 200 = 5.','original'),
('127.812.d.8.B',3,'A team reorders the stations to cut the walking distance between operations and finds they can save time on every part. They are:','["re-examining the manufacturing process to maximize efficiency and minimize costs", "adding delays", "ignoring waste", "raising costs"]'::jsonb,0,'Process improvement.','original'),
('127.812.d.8.B',4,'Reducing unnecessary motion and waiting in a process is a way to:','["slow output", "improve efficiency and lower costs", "raise defects", "increase waste"]'::jsonb,1,'Efficiency lowers cost.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_111_v1'
from (values
('127.812.d.9.A',3,'A student group writes a marketing plan for an engraved cutting board, listing target buyers, price, a sales channel and promotion ideas. They are preparing:','["a cafeteria menu", "a game schedule", "a marketing plan for a product", "a class roster"]'::jsonb,2,'Marketing plans promote products.','original'),
('127.812.d.9.A',4,'The price in a marketing plan is set so that it:','["is as low as possible", "is as high as possible", "is random", "covers costs and is acceptable to the target customers"]'::jsonb,3,'Price balances cost and value.','original'),
('127.812.d.9.B',3,'After several buyers post reviews that the handles loosen quickly, repeat orders drop and the brand''s reputation suffers. Students are analyzing:','["the effect of customer satisfaction on a product''s image", "the effect of rain on grass", "the effect of music on sleep", "the effect of food on mood"]'::jsonb,0,'Satisfaction affects image.','original'),
('127.812.d.9.B',4,'A company can protect its image by:','["hiding problems", "fixing defects and responding to customer feedback", "raising prices only", "ignoring complaints"]'::jsonb,1,'Respond to feedback.','original'),
('127.812.d.9.C',3,'Buyers say a toolbox is too heavy and hard to carry, so engineers redesign it with lighter material and a better handle. They are analyzing how:','["sunlight affects plants", "sleep affects mood", "customer demands influence the design of an object", "rain affects roads"]'::jsonb,2,'Design follows demand.','original'),
('127.812.d.9.C',4,'Customer feedback surveys help designers by:','["increasing cost only", "hiding problems", "replacing testing", "showing what features customers want"]'::jsonb,3,'Feedback guides design.','original'),
('127.812.d.10.A',3,'The shift lead uses a standard handoff form and verbally reviews each open job with the incoming lead before leaving. She is demonstrating:','["communication techniques consistent with industry standards", "rumor-passing", "silence", "guessing"]'::jsonb,0,'Handoff standards prevent errors.','original'),
('127.812.d.10.A',4,'A good handoff between shifts includes:','["nothing", "a clear summary of status, issues and what is next", "only gossip", "only the weather"]'::jsonb,1,'Clear handoffs.','original'),
('127.812.d.10.B',3,'Unsure how to program a thread cut, a student checks the machine''s programming manual and the tool vendor''s data sheet. She is:','["quitting", "guessing", "locating relevant information needed to solve problems", "ignoring the problem"]'::jsonb,2,'Find authoritative info.','original'),
('127.812.d.10.B',4,'A tool vendor''s data sheet is a good source for:','["weather", "music reviews", "sports news", "recommended speeds, feeds and materials for a tool"]'::jsonb,3,'Vendor data guides use.','original'),
('127.812.d.10.C',3,'A planner must figure how many 8-inch parts can be cut from a 20-foot bar with each cut wasting a quarter inch. She is applying:','["mathematics concepts to solve manufacturing problems", "calendar dates", "cooking math only", "sports stats"]'::jsonb,0,'Applied arithmetic.','original'),
('127.812.d.10.C',4,'A 120-inch bar is cut into 10-inch pieces. Ignoring waste, how many pieces result?','["10", "12", "14", "11"]'::jsonb,1,'120 ÷ 10 = 12.','original'),
('127.812.d.10.D',3,'A technician explains that coolant keeps a cutting tool from overheating because it carries heat away from the cut. She is analyzing:','["fashion color", "a game score", "science principles used to solve problems", "music tempo"]'::jsonb,2,'Heat transfer principles.','original'),
('127.812.d.10.D',4,'Coolant in machining is used mainly to:','["add color", "make chips stick", "increase noise", "remove heat and lubricate the cut"]'::jsonb,3,'Cooling and lubrication.','original'),
('127.812.d.10.E',3,'An engineer converts a part drawing from inches to millimeters before sending it to an overseas shop, writing the unit on every dimension. She is using:','["appropriate units of measure", "no units", "random units", "mixed units"]'::jsonb,0,'Units must be consistent.','original'),
('127.812.d.10.E',4,'One inch is equal to:','["12 millimeters", "25.4 millimeters", "10 millimeters", "100 millimeters"]'::jsonb,1,'1 in = 25.4 mm.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
